 46	/// Composes transforms so points pass through `right` first, then `left`.
 47	pub fn affine_compose(left: Affine, right: Affine) -> Option<Affine> {
 48	    if !affine_valid(left) || !affine_valid(right) {
 49	        return None;
 50	    }
 51	    let result = Affine {
 52	        a: left.a * right.a + left.c * right.b,
 53	        b: left.b * right.a + left.d * right.b,
 54	        c: left.a * right.c + left.c * right.d,
 55	        d: left.b * right.c + left.d * right.d,
 56	        e: left.a * right.e + left.c * right.f + left.e,
 57	        f: left.b * right.e + left.d * right.f + left.f,
 58	    };
 59	    affine_valid(result).then_some(result)
 60	}
130	pub fn parse_transform_node(attributes: AttributeList<'_>, parent: Affine) -> Result<(Affine, usize), TransformError> {
131	    let Some(span) = attributes.get(b"transform") else { return Ok((parent, 0)); };
132	    let (local, operations) = parse_transform(attributes.source(), span)
133	        .map_err(|_| TransformError { offset: span.start })?;
134	    let composed = affine_compose(parent, local)
135	        .ok_or(TransformError { offset: attributes.element_name().start })?;
136	    Ok((composed, operations))
137	}
